<?php require_once __DIR__.'/../includes/functions.php'; if(isset($_GET['logout'])){session_destroy();header('Location: login.php');exit;} if(admin_logged_in()){header('Location: dashboard.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=db();if(($d['admin']['username']==($_POST['username']??''))&&password_verify($_POST['password']??'',$d['admin']['password_hash'])){$_SESSION['admin_logged_in']=1;header('Location: dashboard.php');exit;}$err='Invalid login.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/admin.css"><title>Admin Login</title></head><body><div class="login-wrap"><div class="login-card"><img src="../assets/images/janani-homeopathy-logo.png" style="width:100%;max-width:260px"><h1>Admin Login</h1><?php if($err):?><div class="notice error"><?=e($err)?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn">Login</button></form></div></div></body></html>
